param([Parameter(Mandatory=$true)][string]$RepoRoot)
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop"
function Die([string]$Code,[string]$Detail){throw($Code+":"+$Detail)}
$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path;. (Join-Path $RepoRoot "scripts\storage\_lib_ld_receipts_v1.ps1");$fixture=Join-Path $RepoRoot "scripts\storage\ld_storage03_positive_ready_path_fixture_v1.ps1";$out=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $fixture -RepoRoot $RepoRoot;if($LASTEXITCODE-ne0){Die "FIXTURE_EXIT_NONZERO" ([string]$LASTEXITCODE)};$receipt=LDREC-ReadReceiptFromOutput $out "ld.device.storage03_positive_ready_path_fixture.receipt.v1" (Join-Path $RepoRoot "schemas");if(-not[bool]$receipt.ok){Die "FIXTURE_NOT_OK" ""};if(-not[bool]$receipt.fixture_preflight_ready){Die "PREFLIGHT_NOT_READY" ""};if(-not[bool]$receipt.fixture_contract_execution_allowed_now){Die "CONTRACT_NOT_ALLOWED" ""};if(-not[bool]$receipt.fixture_contract_would_allow_future_bounded_copy){Die "FUTURE_COPY_NOT_ALLOWED" ""};if(-not[bool]$receipt.guard_would_invoke_future_executor){Die "GUARD_DID_NOT_AUTHORIZE" ""};if([int]$receipt.would_execute_count-ne1){Die "WOULD_EXECUTE_COUNT_BAD" ""};if([int]$receipt.would_not_execute_count-ne0){Die "WOULD_NOT_EXECUTE_COUNT_BAD" ""};if([bool]$receipt.performs_copy){Die "PERFORMS_COPY_TRUE" ""};if([bool]$receipt.writes_destination){Die "WRITES_DESTINATION_TRUE" ""};if((LDREC-HexSha256File ([string]$receipt.guard_receipt_path))-cne[string]$receipt.guard_receipt_sha256){Die "GUARD_HASH_MISMATCH" ""};if(([string]$receipt.rows[0].disposition)-cne"WOULD_INVOKE_FUTURE_EXECUTOR"){Die "POSITIVE_ROW_MISSING" ""}
Write-Output "PASS: schema-valid ready contract reached the real guard"
Write-Output "PASS: execution_allowed_now and would_invoke_future_executor are true"
Write-Output "PASS: positive fixture still performs no copy and writes no destination bytes"
Write-Output "SELFTEST_LD_STORAGE03_POSITIVE_READY_PATH_FIXTURE_OK"
